        QPointer<RuleOverlayDialog> dialog=new RuleOverlayDialog(&controller,p.id); dialog->show(); QTRY_COMPARE(dialog->findChild<QTableWidget*>("sourceRulesTable")->rowCount(),1); dialog->findChild<QTabWidget*>("ruleOverlayTabs")->setCurrentIndex(3); dialog->findChild<QPushButton*>("addRuleProvider")->click(); auto* editor=dialog->findChild<QDialog*>("providerDefinitionDialog"); QVERIFY(editor); editor->findChild<QLineEdit*>("ruleProviderName")->setText("Sites"); editor->findChild<QLineEdit*>("ruleProviderUrl")->setText("https://example.invalid/sites"); editor->findChild<QCheckBox*>("addRuleProviderReference")->setChecked(true); editor->findChild<QPushButton*>("stageRuleProvider")->click(); QCOMPARE(network->requests,0); const auto output=qEnvironmentVariable("MLASH_UI_SCREENSHOTS"); if (!output.isEmpty()) { QVERIFY(QDir().mkpath(output)); QCoreApplication::processEvents(); QVERIFY(dialog->grab().save(output+"/provider-staged.png")); } QCOMPARE(dialog->findChild<QTableWidget*>("prependRulesTable")->rowCount(),1); QCOMPARE(dialog->findChild<QTableWidget*>("ruleProviderDefinitions")->rowCount(),1); QCOMPARE(dialog->findChild<QTableWidget*>("ruleProviderDefinitions")->item(0,3)->text(),QString("1"));
