    void validationAndImmutableSnapshots() {
        QVERIFY(validateRuleProviderEdits(declarations()).ok);
        const auto unsupported=ConfigBuilder::build("rule-providers: {sites: {type: http, behavior: domain, url: 'https://example.invalid/sites', header: {Authorization: ['PRIVATE_HEADER_TOKEN']}}}\nrules: ['MATCH,DIRECT']\n",settings(),19090,QString(64,'a')); QVERIFY(!unsupported.result.ok); QCOMPARE(unsupported.result.data["code"].toString(),QString("PROVIDER_HEADER")); QVERIFY(!unsupported.result.error.contains("PRIVATE_HEADER_TOKEN"));

        for (const auto& url:QStringList{"http://example.test/a","https://u:p@example.test/a","https://example.test/a#fragment","https://example.test/a\n"}) QVERIFY(!validateRuleProviderEdits(declarations(url)).ok);
        auto edits=declarations(); auto row=edits["Sites"].toObject(); row["format"]="mrs"; row["behavior"]="classical"; edits["Sites"]=row; QVERIFY(!validateRuleProviderEdits(edits).ok);
        QTemporaryDir data; auto platform=std::make_shared<ProviderPlatform>(); ProfileStore store(data.path(),platform); QVERIFY(store.load().result.ok); auto p=seed(store); QVERIFY(isId(p.candidate)); const auto old=p.candidate; p.ruleProviderEdits=declarations(); p.customRules={"RULE-SET,Sites,Test"};
        auto next=store.prepareExisting(p,old,settings(),19091,QString(64,'b'),true,{providerSnapshotId("rule-providers","Sites")},true); QVERIFY2(next.result.ok,qUtf8Printable(next.result.error)); QCOMPARE(next.result.data["providers"].toArray().size(),1);
        auto frozen=p; QVERIFY(store.versionProfile(p.id,old,frozen).ok); QVERIFY(frozen.ruleProviderEdits.isEmpty()); QVERIFY(frozen.customRules.isEmpty()); QVERIFY(store.versionProfile(p.id,next.version,frozen).ok); QCOMPARE(frozen.ruleProviderEdits,p.ruleProviderEdits);
        QByteArray raw; QVERIFY(readFile(store.versionRoot(p.id,next.version)+"/source.yaml",raw).ok); QCOMPARE(raw,source);
        const auto provider=next.result.data["providers"].toArray()[0].toObject(); const QByteArray payload="payload: ['+.example.test']\n"; QVERIFY(writeAtomic(next.workPath+"/"+provider["path"].toString(),payload).ok); QVERIFY(store.recordProviderSnapshot(next.workPath,provider,payload).ok);
        p.active=next.version; p.candidate=old; const auto offline=store.prepareExisting(p,old,settings(),19092,QString(64,'c')); QVERIFY2(offline.result.ok,qUtf8Printable(offline.result.error)); QVERIFY(offline.result.data["providers"].toArray().isEmpty()); QCOMPARE(offline.profile.updated,p.updated);
        const auto oldProviders=store.inspectProviders(p,old,settings()); QVERIFY(oldProviders.ok); QVERIFY(oldProviders.data["providers"].toArray().isEmpty());
        p.ruleProviderEdits=declarations("https://example.invalid/different"); const auto mismatch=store.prepareExisting(p,old,settings(),19092,QString(64,'d')); QVERIFY(!mismatch.result.ok);
        p.ruleProviderEdits=declarations(); QByteArray manifest; QVERIFY(readFile(next.workPath+"/provider-snapshots.json",manifest).ok); auto records=QJsonDocument::fromJson(manifest).object(); auto record=records[provider["path"].toString()].toObject(); record["source_sha256"]=QString(64,'0'); records[provider["path"].toString()]=record; QVERIFY(writeAtomic(next.workPath+"/provider-snapshots.json",QJsonDocument(records).toJson()).ok); QVERIFY(!BackupArchive::create(store,settings(),{p},data.path()+"/invalid.mlashbackup","provider-backup-password").ok);
        QCOMPARE(platform->writes,0);
    }
    void originalRemovalReferencesLegacyAndCorruption() {
        QTemporaryDir data; auto platform=std::make_shared<ProviderPlatform>(); ProfileStore store(data.path(),platform); QVERIFY(store.load().result.ok); auto p=seed(store); const auto root=store.versionRoot(p.id,p.candidate); QVERIFY(QFile::remove(root+"/overrides.json")); QVERIFY(store.ensureVersionSnapshots(p).ok); auto frozen=p; QVERIFY(store.versionProfile(p.id,p.candidate,frozen).ok); QVERIFY(frozen.ruleProviderEdits.isEmpty());
        QByteArray bytes; QVERIFY(readFile(root+"/source.yaml",bytes).ok); QVERIFY(writeAtomic(root+"/source.yaml",bytes+"# tampered\n").ok); QVERIFY(!store.versionProfile(p.id,p.candidate,frozen).ok); QVERIFY(writeAtomic(root+"/source.yaml",bytes).ok);
        const QByteArray original="rule-providers: {sites: {type: inline, behavior: domain, payload: [example.test]}}\nproxies: []\nproxy-groups: [{name: Test, type: select, proxies: [DIRECT]}]\nrules: ['RULE-SET,sites,Test','MATCH,Test']\n";
        auto prepared=store.prepare(p,original,settings(),19091,QString(64,'a')); QVERIFY(prepared.result.ok); QVERIFY(store.save(settings(),{prepared.profile}).ok); AppController controller(data.path(),true,nullptr,platform); QSignalSpy initialized(&controller,&AppController::initialized),finished(&controller,&AppController::operationFinished); controller.initialize(); QTRY_COMPARE(initialized.size(),1);
        const auto originalVersion=controller.profiles()[0].candidate; const QJsonObject removed{{"sites",QJsonValue(QJsonValue::Null)}}; controller.updateRuleDefinitions(p.id,{},{},{},removed); QTRY_COMPARE_WITH_TIMEOUT(finished.size(),1,15000); QVERIFY(!finished.last()[0].toBool()); QCOMPARE(controller.profiles()[0].candidate,originalVersion); QVERIFY(controller.profiles()[0].ruleProviderEdits.isEmpty());
        controller.updateRuleDefinitions(p.id,{},{},{"RULE-SET,sites,Test"},removed); QTRY_COMPARE_WITH_TIMEOUT(finished.size(),2,15000); QVERIFY2(finished.last()[0].toBool(),qUtf8Printable(finished.last()[1].toString())); bool read=false; controller.inspectRuleSource(p.id,[&](Result result) { QVERIFY2(result.ok,qUtf8Printable(result.error)); QCOMPARE(result.data["rules"].toArray().size(),2); read=true; }); QTRY_VERIFY(read); QCOMPARE(platform->writes,0);
    }
